function tomlStripComment(line){
  var i=line.indexOf(' #');
  if(i>=0) line=line.slice(0,i);
  if(line.charAt(0)==='#') line='';
  return line;
}
function tomlParseValue(raw){
  raw=raw.trim();
  if(raw.charAt(0)==='"'){ var inner=raw.slice(1,-1).replace(/\\n/g,'\n').replace(/\\t/g,'\t').replace(/\\"/g,'"').replace(/\\\\/g,'\\'); return inner; }
  if(raw.charAt(0)==="'"){ return raw.slice(1,-1); }
  if(raw.charAt(0)==='['){ var inner=raw.slice(1,-1).trim(); if(inner==='') return []; return inner.split(',').map(function(x){ return tomlParseValue(x); }); }
  if(raw==='true') return true;
  if(raw==='false') return false;
  if(/^-?\d+$/.test(raw)) return parseInt(raw,10);
  if(/^-?\d*\.\d+$/.test(raw)) return parseFloat(raw);
  return raw;
}
function tomlParse(text){
  var root={}, cur=root;
  var lines=text.split('\n');
  for(var li=0; li<lines.length; li++){
    var line=tomlStripComment(lines[li]).trim();
    if(line==='') continue;
    if(line.charAt(0)==='['){
      var close=line.lastIndexOf(']');
      var header=line.slice(1,close);
      var isArray = header.charAt(0)==='[';
      if(isArray) header=header.slice(1,-1);
      var keys=header.split('.').map(function(x){ return x.trim(); });
      if(isArray){
        var parent=root;
        for(var i=0;i<keys.length-1;i++){ if(parent[keys[i]]===undefined) parent[keys[i]]={}; parent=parent[keys[i]]; }
        var last=keys[keys.length-1];
        if(!Array.isArray(parent[last])) parent[last]=[];
        var newObj={}; parent[last].push(newObj); cur=newObj;
      } else {
        var p=root;
        for(var i2=0;i2<keys.length;i2++){ if(p[keys[i2]]===undefined) p[keys[i2]]={}; p=p[keys[i2]]; }
        cur=p;
      }
      continue;
    }
    var eq=line.indexOf('=');
    if(eq<0) continue;
    var k=line.slice(0,eq).trim();
    cur[k]=tomlParseValue(line.slice(eq+1));
  }
  return root;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tomlParse:tomlParse, tomlParseValue:tomlParseValue };
}
if (typeof window !== 'undefined') {
  window.TomlForgePure = { tomlParse:tomlParse, tomlParseValue:tomlParseValue };
}
